 private long id(ContentValues v){return v.getAsLong("id");}private String str(ContentValues v,String k){return v==null?"":v.getAsString(k);}private long num(ContentValues v,String k){return v.getAsLong(k);}
 private String money(long n){return moneyFormat.format(n)+" đ";}private String initial(String n){return n.isEmpty()?"?":n.substring(0,1).toUpperCase(new Locale("vi","VN"));}
