 private String groupName(){for(ContentValues g:s.groups)if(id(g)==s.groupId)return str(g,"name");return "Chọn nhóm";}
 private void row(List<WorkspaceAdapter.Row> rows,String key,String kind,String title,String detail,String amount,String avatar,ContentValues data){rows.add(new WorkspaceAdapter.Row(key,kind,title,detail,amount,avatar,data));}
